package com.camerascenes;

import com.google.gson.Gson;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CameraScenesBackupServiceTest
{
	@Test
	public void roundTripsFullBackupIncludingHotkeysAndSettings() throws Exception
	{
		KeybindPair keybinds = new KeybindPair();
		CameraScenesViewpoint viewpoint = new CameraScenesViewpoint(0, "Bank", 1234, 3064, 640,
			keybinds.viewpoint, false);
		viewpoint.setNotes("Use this at the bank");
		CameraScenesViewpointSet group = new CameraScenesViewpointSet(0, "Bank scenes");
		group.setEnabled(false);
		group.setExpanded(false);
		group.setPreviousKeybind(keybinds.previous);
		group.setNextKeybind(keybinds.next);
		group.setViewpoints(Arrays.asList(viewpoint));

		CameraScenesBackupService service = new CameraScenesBackupService(new Gson());
		File file = File.createTempFile("camera-scenes-backup", ".json");
		file.deleteOnExit();
		service.write(file, CameraScenesBackup.all(Arrays.asList(group), CameraScenesBackupSettings.from(new CameraScenesConfig() { } )));

		CameraScenesBackup decoded = service.read(file);
		assertEquals(CameraScenesBackup.CURRENT_SCHEMA_VERSION, decoded.getSchemaVersion());
		assertEquals(CameraScenesBackup.SCOPE_ALL, decoded.getScope());
		assertEquals(group, decoded.getGroups().get(0));
		assertTrue(new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8).contains("\"previousKeybind\""));
		assertFalse(decoded.getSettings().isSmoothViewpointLoads());
	}

	@Test(expected = java.io.IOException.class)
	public void rejectsFutureSchemaVersions() throws Exception
	{
		CameraScenesBackupService service = new CameraScenesBackupService(new Gson());
		File file = File.createTempFile("camera-scenes-future", ".json");
		file.deleteOnExit();
		Files.write(file.toPath(), ("{\"schemaVersion\":99,\"format\":\"camera-scenes-backup\","
			+ "\"scope\":\"all\",\"settings\":{},\"groups\":[]}").getBytes(StandardCharsets.UTF_8));
		service.read(file);
	}

	private static final class KeybindPair
	{
		private final net.runelite.client.config.Keybind previous =
			new net.runelite.client.config.Keybind(KeyEvent.VK_P, InputEvent.CTRL_DOWN_MASK);
		private final net.runelite.client.config.Keybind next =
			new net.runelite.client.config.Keybind(KeyEvent.VK_N, InputEvent.CTRL_DOWN_MASK);
		private final net.runelite.client.config.Keybind viewpoint =
			new net.runelite.client.config.Keybind(KeyEvent.VK_B, InputEvent.SHIFT_DOWN_MASK);
	}
}

package com.camerascenes;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class CameraScenesCameraServiceTest
{
	@Test
	public void negativeZoomIsAReadyCameraValue()
	{
		assertTrue(CameraScenesCameraService.hasReadyCameraState(-94, 1922));
		assertTrue(CameraScenesCameraService.hasReadyCameraState(527, 0));
	}

	@Test
	public void zeroZoomAndPitchStillRepresentUninitializedCameraState()
	{
		assertFalse(CameraScenesCameraService.hasReadyCameraState(0, 0));
	}

	@Test
	public void cameraSettledAllowsSmallClientRoundingDifference()
	{
		assertTrue(CameraScenesCameraService.hasCameraSettled(1023, 256, 1024, 256));
		assertTrue(CameraScenesCameraService.hasCameraSettled(1024, 257, 1024, 256));
		assertFalse(CameraScenesCameraService.hasCameraSettled(1020, 256, 1024, 256));
	}

	@Test
	public void cameraSettledHandlesYawWraparound()
	{
		assertTrue(CameraScenesCameraService.hasCameraSettled(16383, 256, 0, 256));
	}
}

package com.camerascenes;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.util.Arrays;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.client.config.Keybind;
import org.junit.Test;

public class CameraScenesViewpointCatalogTest
{
	@Test
	public void normalizesLoadedIdsAndNullCollections()
	{
		CameraScenesViewpointSet viewpointSet = new CameraScenesViewpointSet();
		viewpointSet.setId(99);
		viewpointSet.setViewpoints(null);
		CameraScenesViewpointCatalog catalog = new CameraScenesViewpointCatalog();
		catalog.replaceAll(Arrays.asList(viewpointSet));

		assertEquals(0, catalog.listAllSets().get(0).getId());
		assertEquals(0, catalog.listAllSets().get(0).getViewpoints().size());
	}

	@Test
	public void cyclesEnabledPointsAndWraps()
	{
		CameraScenesViewpointSet viewpointSet = new CameraScenesViewpointSet(0, "Group");
		CameraScenesViewpoint first = new CameraScenesViewpoint(0, "First", 0, 128, 512, null, true);
		CameraScenesViewpoint second = new CameraScenesViewpoint(1, "Second", 0, 128, 512, null, true);
		viewpointSet.setViewpoints(Arrays.asList(first, second));
		CameraScenesViewpointCatalog catalog = new CameraScenesViewpointCatalog();
		catalog.replaceAll(Arrays.asList(viewpointSet));

		assertSame(first, catalog.advance(viewpointSet));
		assertSame(second, catalog.advance(viewpointSet));
		assertSame(first, catalog.advance(viewpointSet));
		assertSame(second, catalog.rewind(viewpointSet));
	}

	@Test
	public void tracksCurrentViewpointAndNotifiesListeners()
	{
		CameraScenesViewpointSet viewpointSet = new CameraScenesViewpointSet(0, "Group");
		CameraScenesViewpoint first = new CameraScenesViewpoint(0, "First", 0, 128, 512, null, true);
		CameraScenesViewpoint second = new CameraScenesViewpoint(1, "Second", 0, 128, 512, null, true);
		viewpointSet.setViewpoints(Arrays.asList(first, second));
		CameraScenesViewpointCatalog catalog = new CameraScenesViewpointCatalog();
		AtomicInteger notifications = new AtomicInteger();
		catalog.addSelectionListener(notifications::incrementAndGet);
		catalog.replaceAll(Arrays.asList(viewpointSet));

		catalog.markSelected(viewpointSet, second);
		catalog.markSelected(viewpointSet, second);

		assertFalse(catalog.isCurrent(viewpointSet, first));
		assertTrue(catalog.isCurrent(viewpointSet, second));
		assertEquals(1, notifications.get());
	}

	@Test
	public void rejectsActiveDuplicateKeybindsButIgnoresDisabledGroups()
	{
		Keybind keybind = new Keybind(KeyEvent.VK_A, InputEvent.CTRL_DOWN_MASK);
		CameraScenesViewpoint first = new CameraScenesViewpoint(0, "First", 0, 128, 512, keybind, true);
		CameraScenesViewpoint second = new CameraScenesViewpoint(0, "Second", 0, 128, 512, keybind, true);
		CameraScenesViewpointSet activeGroup = new CameraScenesViewpointSet(0, "Active");
		CameraScenesViewpointSet disabledGroup = new CameraScenesViewpointSet(1, "Disabled");
		activeGroup.setViewpoints(Arrays.asList(first));
		disabledGroup.setEnabled(false);
		disabledGroup.setViewpoints(Arrays.asList(second));
		CameraScenesViewpointCatalog catalog = new CameraScenesViewpointCatalog();
		catalog.replaceAll(Arrays.asList(activeGroup, disabledGroup));

		assertNull(catalog.findActiveKeybindConflict(keybind, activeGroup, first, false));
		Keybind groupKeybind = new Keybind(KeyEvent.VK_C, 0);
		activeGroup.setPreviousKeybind(groupKeybind);
		assertNull(catalog.findActiveKeybindConflict(groupKeybind, activeGroup, null, false));

		activeGroup.setViewpoints(Arrays.asList(first, second));
		assertNotNull(catalog.findActiveKeybindConflict(keybind, activeGroup, first, false));
	}

	@Test
	public void treatsDeserializedNotSetValuesAsUnset()
	{
		Keybind persistedNotSet = new Keybind(Keybind.NOT_SET.getKeyCode(), Keybind.NOT_SET.getModifiers());
		CameraScenesViewpoint viewpoint = new CameraScenesViewpoint(0, "First", 0, 128, 512, persistedNotSet, true);
		CameraScenesViewpointSet viewpointSet = new CameraScenesViewpointSet(0, "Group");
		viewpointSet.setViewpoints(Arrays.asList(viewpoint));
		viewpointSet.setPreviousKeybind(persistedNotSet);

		CameraScenesViewpointCatalog catalog = new CameraScenesViewpointCatalog();
		catalog.replaceAll(Arrays.asList(viewpointSet));

		assertSame(Keybind.NOT_SET, viewpoint.getKeybind());
		assertSame(Keybind.NOT_SET, viewpointSet.getPreviousKeybind());
		assertTrue(catalog.listAllActiveKeybindConflicts().isEmpty());
	}

	@Test
	public void detectsConflictWhenDisabledGroupIsEnabled()
	{
		Keybind keybind = new Keybind(KeyEvent.VK_B, 0);
		CameraScenesViewpoint activeViewpoint = new CameraScenesViewpoint(0, "Active", 0, 128, 512, keybind, true);
		CameraScenesViewpointSet activeGroup = new CameraScenesViewpointSet(0, "Active");
		activeGroup.setViewpoints(Arrays.asList(activeViewpoint));
		CameraScenesViewpointSet disabledGroup = new CameraScenesViewpointSet(1, "Disabled");
		disabledGroup.setEnabled(false);
		disabledGroup.setNextKeybind(keybind);
		CameraScenesViewpointCatalog catalog = new CameraScenesViewpointCatalog();
		catalog.replaceAll(Arrays.asList(activeGroup, disabledGroup));

		assertNotNull(catalog.findGroupActivationConflict(disabledGroup));
	}

	@Test
	public void clearsOnlyActiveConflictsWhenReassigning()
	{
		Keybind keybind = new Keybind(KeyEvent.VK_D, 0);
		CameraScenesViewpoint activeViewpoint = new CameraScenesViewpoint(0, "Active", 0, 128, 512, keybind, true);
		CameraScenesViewpoint disabledViewpoint = new CameraScenesViewpoint(0, "Disabled", 0, 128, 512, keybind, true);
		CameraScenesViewpointSet activeGroup = new CameraScenesViewpointSet(0, "Active");
		CameraScenesViewpointSet disabledGroup = new CameraScenesViewpointSet(1, "Disabled");
		activeGroup.setViewpoints(Arrays.asList(activeViewpoint));
		disabledGroup.setEnabled(false);
		disabledGroup.setViewpoints(Arrays.asList(disabledViewpoint));
		CameraScenesViewpointCatalog catalog = new CameraScenesViewpointCatalog();
		catalog.replaceAll(Arrays.asList(activeGroup, disabledGroup));

		assertEquals(1, catalog.clearActiveKeybindConflicts(keybind, disabledGroup, disabledViewpoint, false));
		assertEquals(Keybind.NOT_SET, activeViewpoint.getKeybind());
		assertEquals(keybind, disabledViewpoint.getKeybind());
	}

	@Test
	public void clearsActiveConflictsWhenGroupIsActivated()
	{
		Keybind keybind = new Keybind(KeyEvent.VK_E, 0);
		CameraScenesViewpoint activeViewpoint = new CameraScenesViewpoint(0, "Active", 0, 128, 512, keybind, true);
		CameraScenesViewpointSet activeGroup = new CameraScenesViewpointSet(0, "Active");
		activeGroup.setViewpoints(Arrays.asList(activeViewpoint));
		CameraScenesViewpointSet disabledGroup = new CameraScenesViewpointSet(1, "Disabled");
		disabledGroup.setEnabled(false);
		disabledGroup.setNextKeybind(keybind);
		CameraScenesViewpointCatalog catalog = new CameraScenesViewpointCatalog();
		catalog.replaceAll(Arrays.asList(activeGroup, disabledGroup));

		assertNotNull(catalog.findGroupActivationConflict(disabledGroup));
		assertEquals(1, catalog.clearGroupActivationConflicts(disabledGroup));
		assertEquals(Keybind.NOT_SET, activeViewpoint.getKeybind());
		assertFalse(disabledGroup.isEnabled());
	}

	@Test
	public void listsAllConflictsForGroupActivation()
	{
		Keybind firstKeybind = new Keybind(KeyEvent.VK_F, 0);
		Keybind secondKeybind = new Keybind(KeyEvent.VK_G, 0);
		CameraScenesViewpoint firstActiveViewpoint = new CameraScenesViewpoint(0, "First active", 0, 128, 512, firstKeybind, true);
		CameraScenesViewpoint secondActiveViewpoint = new CameraScenesViewpoint(1, "Second active", 0, 128, 512, secondKeybind, true);
		CameraScenesViewpointSet activeGroup = new CameraScenesViewpointSet(0, "Active");
		activeGroup.setViewpoints(Arrays.asList(firstActiveViewpoint, secondActiveViewpoint));
		CameraScenesViewpointSet disabledGroup = new CameraScenesViewpointSet(1, "Disabled");
		disabledGroup.setEnabled(false);
		disabledGroup.setPreviousKeybind(firstKeybind);
		disabledGroup.setNextKeybind(secondKeybind);
		CameraScenesViewpointCatalog catalog = new CameraScenesViewpointCatalog();
		catalog.replaceAll(Arrays.asList(activeGroup, disabledGroup));

		assertEquals(2, catalog.listGroupActivationConflicts(disabledGroup).size());
	}
}

package com.camerascenes;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CameraScenesCameraInterpolationTest
{
	@Test
	public void yawUsesTheShortestWraparoundPath()
	{
		assertEquals(0, CameraScenesCameraInterpolation.yaw(16380, 4, 0.5));
		assertEquals(0, CameraScenesCameraInterpolation.yaw(4, 16380, 0.5));
		assertEquals(16383, CameraScenesCameraInterpolation.yaw(16383, 16383, 1.0));
		assertEquals(0, CameraScenesCameraInterpolation.yaw(0, 0, 1.0));
	}

	@Test
	public void linearInterpolationReachesBothEndpoints()
	{
		assertEquals(150, CameraScenesCameraInterpolation.linear(50, 150, 1.0));
		assertEquals(50, CameraScenesCameraInterpolation.linear(50, 150, 0.0));
		assertEquals(-272, CameraScenesCameraInterpolation.linear(512, -272, 1.0));
		assertEquals(1400, CameraScenesCameraInterpolation.linear(-272, 1400, 1.0));
		assertEquals(0.5, CameraScenesCameraInterpolation.easeInOut(0.5), 0.000001);
		assertEquals(0.5, CameraScenesCameraInterpolation.zoomEaseInOut(0.5), 0.000001);
		assertTrue(CameraScenesCameraInterpolation.zoomEaseInOut(0.9)
			> CameraScenesCameraInterpolation.easeInOut(0.9));
	}
}

package com.camerascenes;

import com.google.gson.Gson;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CameraScenesViewpointTest
{
	@Test
	public void captureNormalizesAndClampsCameraValues()
	{
		CameraScenesViewpoint viewpoint = new CameraScenesViewpoint();
		viewpoint.capture(-1, 9999, -9999);

		assertEquals(CameraScenesViewpoint.YAW_UNITS - 1, viewpoint.getYaw());
		assertEquals(CameraScenesViewpoint.MAX_PITCH, viewpoint.getPitch());
		assertEquals(CameraScenesViewpoint.MIN_ZOOM, viewpoint.getZoom());
	}

	@Test
	public void yawPreservesSpecificCameraDirection()
	{
		CameraScenesViewpoint viewpoint = new CameraScenesViewpoint();
		viewpoint.setYaw(3000);
		assertEquals(3000, viewpoint.getYaw());

		viewpoint.setYaw(-1);
		assertEquals(CameraScenesViewpoint.YAW_UNITS - 1, viewpoint.getYaw());
	}

	@Test
	public void supportsExtendedPitchValues()
	{
		CameraScenesViewpoint viewpoint = new CameraScenesViewpoint();
		viewpoint.setPitch(3064);

		assertEquals(3064, viewpoint.getPitch());
	}

	@Test
	public void identifiesPitchOutsideTheDefaultCameraRange()
	{
		assertFalse(CameraScenesViewpoint.usesExtendedPitch(CameraScenesViewpoint.DEFAULT_MIN_PITCH));
		assertFalse(CameraScenesViewpoint.usesExtendedPitch(CameraScenesViewpoint.DEFAULT_MAX_PITCH));
		assertTrue(CameraScenesViewpoint.usesExtendedPitch(CameraScenesViewpoint.MIN_PITCH));
		assertTrue(CameraScenesViewpoint.usesExtendedPitch(CameraScenesViewpoint.MAX_PITCH));
	}

	@Test
	public void acceptsTheFullSupportedPitchAndZoomBoundaries()
	{
		CameraScenesViewpoint viewpoint = new CameraScenesViewpoint();
		viewpoint.setPitch(CameraScenesViewpoint.MIN_PITCH);
		assertEquals(CameraScenesViewpoint.MIN_PITCH, viewpoint.getPitch());
		viewpoint.setPitch(CameraScenesViewpoint.MAX_PITCH);
		assertEquals(CameraScenesViewpoint.MAX_PITCH, viewpoint.getPitch());

		viewpoint.setZoom(CameraScenesViewpoint.MIN_ZOOM);
		assertEquals(CameraScenesViewpoint.MIN_ZOOM, viewpoint.getZoom());
		viewpoint.setZoom(0);
		assertEquals(0, viewpoint.getZoom());
		viewpoint.setZoom(CameraScenesViewpoint.MAX_ZOOM);
		assertEquals(CameraScenesViewpoint.MAX_ZOOM, viewpoint.getZoom());
	}

	@Test
	public void notesAreOptionalAndNullSafe()
	{
		CameraScenesViewpoint viewpoint = new CameraScenesViewpoint();
		assertEquals("", viewpoint.getNotes());

		viewpoint.setNotes("South-facing bank viewpoint");
		assertEquals("South-facing bank viewpoint", viewpoint.getNotes());

		viewpoint.setNotes(null);
		assertEquals("", viewpoint.getNotes());
	}

	@Test
	public void keepsLegacyViewpointArrayStorageKey()
	{
		CameraScenesViewpointSet viewpointSet = new Gson().fromJson(
			"{\"points\":[{\"name\":\"Legacy view\"}]}", CameraScenesViewpointSet.class);

		assertEquals("Legacy view", viewpointSet.getViewpoints().get(0).getName());
		assertTrue(new Gson().toJson(viewpointSet).contains("\"points\""));
	}
}

package com.camerascenes;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Keybind;
import org.junit.Test;

public class CameraScenesViewpointHistoryTest
{
	@Test
	public void undoAndRedoRestoreOnlyCameraState()
	{
		Keybind originalKeybind = new Keybind(KeyEvent.VK_A, InputEvent.CTRL_DOWN_MASK);
		Keybind changedKeybind = new Keybind(KeyEvent.VK_B, InputEvent.SHIFT_DOWN_MASK);
		CameraScenesViewpoint viewpoint = new CameraScenesViewpoint(0, "Original", 100, 200, 500,
			originalKeybind, true);
		viewpoint.setNotes("Original notes");
		CameraScenesViewpointHistory history = new CameraScenesViewpointHistory();

		history.recordBeforeMutation(viewpoint);
		viewpoint.setName("Changed");
		viewpoint.setNotes("Changed notes");
		viewpoint.setYaw(3000);
		viewpoint.setPitch(400);
		viewpoint.setZoom(600);
		viewpoint.setKeybind(changedKeybind);
		viewpoint.setEnabled(false);

		assertTrue(history.undo(viewpoint));
		assertEquals("Changed", viewpoint.getName());
		assertEquals("Changed notes", viewpoint.getNotes());
		assertEquals(100, viewpoint.getYaw());
		assertEquals(200, viewpoint.getPitch());
		assertEquals(500, viewpoint.getZoom());
		assertEquals(changedKeybind, viewpoint.getKeybind());
		assertFalse(viewpoint.isEnabled());
		assertTrue(history.canRedo(viewpoint));

		assertTrue(history.redo(viewpoint));
		assertEquals("Changed", viewpoint.getName());
		assertEquals("Changed notes", viewpoint.getNotes());
		assertEquals(3000, viewpoint.getYaw());
		assertEquals(400, viewpoint.getPitch());
		assertEquals(600, viewpoint.getZoom());
		assertEquals(changedKeybind, viewpoint.getKeybind());
		assertFalse(viewpoint.isEnabled());
	}

	@Test
	public void rapidEditsCoalesceAndNewEditsClearRedo()
	{
		CameraScenesViewpoint viewpoint = new CameraScenesViewpoint();
		CameraScenesViewpointHistory history = new CameraScenesViewpointHistory();

		history.recordBeforeMutation(viewpoint);
		viewpoint.setYaw(10);
		history.recordBeforeMutation(viewpoint);
		viewpoint.setYaw(20);

		assertTrue(history.undo(viewpoint));
		assertEquals(0, viewpoint.getYaw());
		assertFalse(history.canUndo(viewpoint));
		assertTrue(history.canRedo(viewpoint));

		history.recordBeforeMutation(viewpoint);
		viewpoint.setYaw(30);
		assertFalse(history.canRedo(viewpoint));
	}
}

package com.camerascenes;

import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class CameraScenesConfigMigrationTest
{
	@Test
	public void copiesLegacyValuesIntoNewNamespaceWithoutDeletingLegacyValues()
	{
		Map<String, String> values = new HashMap<>();
		values.put("eye-spy.groups", "legacy groups");
		values.put("eye-spy.smoothViewpointLoads", "true");

		migrate(values);

		assertEquals("legacy groups", values.get("camera-scenes.groups"));
		assertEquals("true", values.get("camera-scenes.smoothViewpointLoads"));
		assertEquals("legacy groups", values.get("eye-spy.groups"));
	}

	@Test
	public void preservesExistingNewValuesAndDoesNotMigrateRetiredKeys()
	{
		Map<String, String> values = new HashMap<>();
		values.put("camera-scenes.groups", "new groups");
		values.put("eye-spy.groups", "legacy groups");
		values.put("eye-spy.disableWhileTyping", "false");

		migrate(values);

		assertEquals("new groups", values.get("camera-scenes.groups"));
		assertNull(values.get("camera-scenes.disableWhileTyping"));
	}

	private static void migrate(Map<String, String> values)
	{
		CameraScenesConfigMigration.migrate(new CameraScenesConfigMigration.Configuration()
		{
			@Override
			public String get(String group, String key)
			{
				return values.get(group + "." + key);
			}

			@Override
			public void set(String group, String key, String value)
			{
				values.put(group + "." + key, value);
			}
		});
	}
}

