package com.camerascenes;

import java.util.Arrays;
import java.util.List;

/** Copies saved settings from the plugin's former config namespace. */
final class CameraScenesConfigMigration
{
	static final String LEGACY_GROUP = "eye-spy";
	private static final List<String> KEYS = Arrays.asList(
		"groups",
		"smoothViewpointLoads",
		"viewpointLoadDuration",
		"smoothZoomLoads",
		"showDebugTextInSidePanel");

	private CameraScenesConfigMigration()
	{
	}

	static void migrate(Configuration configuration)
	{
		for (String key : KEYS)
		{
			if (configuration.get(CameraScenesConfig.GROUP, key) != null)
			{
				continue;
			}

			String legacyValue = configuration.get(LEGACY_GROUP, key);
			if (legacyValue != null)
			{
				configuration.set(CameraScenesConfig.GROUP, key, legacyValue);
			}
		}
	}

	interface Configuration
	{
		String get(String group, String key);

		void set(String group, String key, String value);
	}
}

package com.camerascenes;

import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.KeyCode;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.callback.ClientThread;

/** Bridges saved Camera Scenes viewpoints to RuneLite's client thread. */
@Singleton
final class CameraScenesCameraService
{
	static final int ATTACHED_CAMERA_MODE = 0;
	static final int DETACHED_CAMERA_MODE = 1;
	private static final int CAMERA_SETTLE_TOLERANCE = 2;
	private final Client client;
	private final ClientThread clientThread;
	private final CameraScenesConfig config;
	private CameraScenesViewpoint queuedViewpoint;
	@Inject private CameraScenesLoadTrace trace;
	private String tracePhase = "idle";
	private double traceProgress;

	@Inject
	CameraScenesCameraService(Client client, ClientThread clientThread, CameraScenesConfig config)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
	}

	void captureCurrent(Consumer<CameraScenesCameraSnapshot> snapshotConsumer)
	{
		readCurrent(state ->
		{
			if (state != null)
			{
				// Keyboard camera movement updates RuneLite's targets first; capture those
				// values so a viewpoint stores the requested angle instead of a transient
				// rendered value while the camera is still easing into position.
				snapshotConsumer.accept(new CameraScenesCameraSnapshot(
					state.getYawTarget(), state.getPitchTarget(), state.getZoom()));
			}
		});
	}

	void readCurrent(Consumer<CameraScenesCameraState> stateConsumer)
	{
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				SwingUtilities.invokeLater(() -> stateConsumer.accept(null));
				return;
			}
			CameraScenesCameraState state = new CameraScenesCameraState(
				client.getCameraYaw(),
				client.getCameraPitch(),
				client.getCameraYawTarget(),
				client.getCameraPitchTarget(),
				currentZoom());
			state.setDiagnostics("Mode " + client.getCameraMode() + " | " + tracePhase
				+ " | " + Math.round(traceProgress * 100) + "%"
				+ "<br>Target Y/P: " + client.getCameraYawTarget() + " / " + client.getCameraPitchTarget()
				+ "<br>Camera XYZ: " + client.getCameraX() + " / " + client.getCameraY() + " / " + client.getCameraZ()
				+ "<br>Focus XYZ: " + client.getCameraFocalPointX() + " / " + client.getCameraFocalPointY() + " / " + client.getCameraFocalPointZ()
				+ "<br>" + trace.status());
			SwingUtilities.invokeLater(() -> stateConsumer.accept(state));
		});
	}

	void apply(CameraScenesViewpoint savedViewpoint)
	{
		if (savedViewpoint == null) return;
		long requestedAt = System.nanoTime();
		clientThread.invokeLater(() ->
		{
			trace.begin(requestedAt, savedViewpoint, config);
			tracePhase = "requested";
			traceProgress = 0;
			traceSample("load_request");
			if (client.getGameState() != GameState.LOGGED_IN) return;
			queuedViewpoint = savedViewpoint;
			if (isCameraReady() && !isCutsceneActive())
			{
				startQueuedTransition();
			}
		});
	}

	void onBeforeRender()
	{
		if (!config.showDebugTextInSidePanel()) trace.finish("debug disabled");
		traceSample("before_update");
		try { updateCamera(); }
		finally
		{
			traceSample("after_update");
			if (queuedViewpoint == null) trace.landed();
		}
	}

	private void traceSample(String event)
	{
		trace.sample(client, event, tracePhase, traceProgress, isCameraInputActive(), isCutsceneActive());
	}

	private void updateCamera()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			queuedViewpoint = null;
			return;
		}

		if (queuedViewpoint != null)
		{
			if (isCameraInputActive())
			{
				queuedViewpoint = null;
				return;
			}
			if (!isCameraReady() || isCutsceneActive())
			{
				return;
			}
			startQueuedTransition();
		}

	}

	void cancelPendingLoad()
	{
		trace.finish("cancelled or shutdown");
		queuedViewpoint = null;
	}

	void returnToAttachedCamera()
	{
		clientThread.invokeLater(() -> {
			cancelPendingLoad();
			if (client.getGameState() == GameState.LOGGED_IN && client.getCameraMode() == DETACHED_CAMERA_MODE)
			{
				client.setCameraMode(ATTACHED_CAMERA_MODE);
			}
		});
	}

	private void startQueuedTransition()
	{
		CameraScenesViewpoint viewpoint = queuedViewpoint;
		queuedViewpoint = null;
		if (viewpoint == null || !isCameraReady() || isCutsceneActive())
		{
			return;
		}
		applyImmediate(viewpoint);
	}

	private boolean isCameraReady()
	{
		return client.getGameState() == GameState.LOGGED_IN
			&& hasReadyCameraState(currentZoom(), client.getCameraPitchTarget());
	}

	static boolean hasReadyCameraState(int zoom, int pitchTarget)
	{
		// Camera Scenes supports the game's negative zoom values. During early
		// initialization both values are zero, so retain a lightweight readiness guard.
		return zoom != 0 || pitchTarget > 0;
	}

	private boolean isCutsceneActive()
	{
		return client.getVarbitValue(VarbitID.CUTSCENE_STATUS) != 0;
	}

	private boolean isCameraInputActive()
	{
		return client.isKeyPressed(KeyCode.KC_UP)
			|| client.isKeyPressed(KeyCode.KC_DOWN)
			|| client.isKeyPressed(KeyCode.KC_LEFT)
			|| client.isKeyPressed(KeyCode.KC_RIGHT)
			|| client.getMouseCurrentButton() == 2
			|| client.getMouseCurrentButton() == 4;
	}

	private void applyImmediate(CameraScenesViewpoint savedViewpoint)
	{
		int originalCameraMode = client.getCameraMode();
		boolean restoreAttachedCamera = originalCameraMode == ATTACHED_CAMERA_MODE;
		if (restoreAttachedCamera)
		{
			client.setCameraMode(DETACHED_CAMERA_MODE);
			traceSample("entered_detached_mode");
		}

		if (client.getCameraMode() != DETACHED_CAMERA_MODE)
		{
			tracePhase = "detached-mode-unavailable";
			trace.finish("detached camera unavailable");
			return;
		}

		tracePhase = "detached-orientation-and-zoom-load";
		client.setCameraYawTarget(CameraScenesViewpoint.normalizeYaw(savedViewpoint.getYaw()));
		client.setCameraPitchTarget(savedViewpoint.getPitch());
		client.runScript(ScriptID.CAMERA_DO_ZOOM, savedViewpoint.getZoom(), savedViewpoint.getZoom());

		if (restoreAttachedCamera && client.getGameState() == GameState.LOGGED_IN
			&& client.getCameraMode() == DETACHED_CAMERA_MODE)
		{
			traceSample("before_reattach");
			client.setCameraMode(ATTACHED_CAMERA_MODE);
			tracePhase = "post-load";
			traceSample("after_reattach");
		}
		trace.landed();
	}

	static boolean hasCameraSettled(int currentYaw, int currentPitch, int targetYaw, int targetPitch)
	{
		int yawDelta = Math.abs(Math.floorMod(currentYaw - targetYaw + CameraScenesViewpoint.YAW_UNITS / 2,
			CameraScenesViewpoint.YAW_UNITS) - CameraScenesViewpoint.YAW_UNITS / 2);
		return yawDelta <= CAMERA_SETTLE_TOLERANCE
			&& Math.abs(currentPitch - targetPitch) <= CAMERA_SETTLE_TOLERANCE;
	}

	private int currentZoom()
	{
		return client.getVarcIntValue(VarClientID.CAMERA_ZOOM_BIG);
	}

}

package com.camerascenes;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.IdentityHashMap;
import java.util.Map;
import javax.inject.Singleton;

/** Keeps a bounded, session-only camera-value history for individual viewpoints. */
@Singleton
final class CameraScenesViewpointHistory
{
	private static final int MAX_HISTORY_ENTRIES = 20;
	private static final long COALESCE_WINDOW_NANOS = 750_000_000L;

	private final Map<CameraScenesViewpoint, ViewpointHistory> histories = new IdentityHashMap<>();

	void recordBeforeMutation(CameraScenesViewpoint viewpoint)
	{
		if (viewpoint == null)
		{
			return;
		}

		ViewpointHistory history = histories.computeIfAbsent(viewpoint, ignored -> new ViewpointHistory());
		long now = System.nanoTime();
		if (history.undo.isEmpty() || now - history.lastCheckpointNanos > COALESCE_WINDOW_NANOS)
		{
			history.undo.addLast(ViewpointState.capture(viewpoint));
			trim(history.undo);
		}
		history.lastCheckpointNanos = now;
		history.redo.clear();
	}

	boolean canUndo(CameraScenesViewpoint viewpoint)
	{
		ViewpointHistory history = histories.get(viewpoint);
		return history != null && !history.undo.isEmpty();
	}

	boolean canRedo(CameraScenesViewpoint viewpoint)
	{
		ViewpointHistory history = histories.get(viewpoint);
		return history != null && !history.redo.isEmpty();
	}

	boolean undo(CameraScenesViewpoint viewpoint)
	{
		ViewpointHistory history = histories.get(viewpoint);
		if (history == null || history.undo.isEmpty())
		{
			return false;
		}

		history.redo.addLast(ViewpointState.capture(viewpoint));
		trim(history.redo);
		history.undo.removeLast().applyTo(viewpoint);
		history.lastCheckpointNanos = 0;
		return true;
	}

	boolean redo(CameraScenesViewpoint viewpoint)
	{
		ViewpointHistory history = histories.get(viewpoint);
		if (history == null || history.redo.isEmpty())
		{
			return false;
		}

		history.undo.addLast(ViewpointState.capture(viewpoint));
		trim(history.undo);
		history.redo.removeLast().applyTo(viewpoint);
		history.lastCheckpointNanos = 0;
		return true;
	}

	void clearAll()
	{
		histories.clear();
	}

	private static void trim(Deque<ViewpointState> states)
	{
		while (states.size() > MAX_HISTORY_ENTRIES)
		{
			states.removeFirst();
		}
	}

	private static final class ViewpointHistory
	{
		private final Deque<ViewpointState> undo = new ArrayDeque<>();
		private final Deque<ViewpointState> redo = new ArrayDeque<>();
		private long lastCheckpointNanos;
	}

	private static final class ViewpointState
	{
		private final int yaw;
		private final int pitch;
		private final int zoom;

		private ViewpointState(int yaw, int pitch, int zoom)
		{
			this.yaw = yaw;
			this.pitch = pitch;
			this.zoom = zoom;
		}

		private static ViewpointState capture(CameraScenesViewpoint viewpoint)
		{
			return new ViewpointState(viewpoint.getYaw(), viewpoint.getPitch(), viewpoint.getZoom());
		}

		private void applyTo(CameraScenesViewpoint viewpoint)
		{
			viewpoint.setYaw(yaw);
			viewpoint.setPitch(pitch);
			viewpoint.setZoom(zoom);
		}
	}
}

